import{_ as s,c as i,o as e,ai as n}from"./chunks/framework.B63Sb1io.js";const t="/img/png/408_DS/13.png",l="/img/png/408_DS/14.png",b=JSON.parse('{"title":"队列的链式存储结构","titleTemplate":"数据结构","description":"队列的链式存储结构","frontmatter":{"title":"队列的链式存储结构","titleTemplate":"数据结构","description":"队列的链式存储结构","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false,"tags":["数据结构","队列","链式存储","408"]},"headers":[],"relativePath":"post/kaoyan/408/408_DS/03/408_DS_8.md","filePath":"post/kaoyan/408/408_DS/03/408_DS_8.md","lastUpdated":1756123810000}'),r={name:"post/kaoyan/408/408_DS/03/408_DS_8.md"};function p(d,a,h,o,c,k){return e(),i("div",null,a[0]||(a[0]=[n('<h1 id="队列的链式存储结构" tabindex="-1">队列的链式存储结构 <a class="header-anchor" href="#队列的链式存储结构" aria-label="Permalink to &quot;队列的链式存储结构&quot;">​</a></h1><h2 id="队列的链式存储" tabindex="-1">队列的链式存储 <a class="header-anchor" href="#队列的链式存储" aria-label="Permalink to &quot;队列的链式存储&quot;">​</a></h2><p>队列的链式表示称为链式队列，它实际上是一个同时有队首指针和队尾指针的单链表，如图所示。队首指针指向队头结点，队尾指针指向队尾结点，即单链表的最后一个结点。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+t+`" alt="链栈" width="450px" style="border-radius:10px;"></div><br><p>队列的链式存储类型可描述为：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkNode{</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //链式队列结点</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ElemType data;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkNode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">next;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}LinkNode;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //链式队列</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LinkNode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">front,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rear;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //队列的队头和队尾指针</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} LinkQueue;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>不带头结点时，当 <code>Q.front==NULL</code> 且 <code>Q.rear==NULL</code> 时，链式队列为空。</p><br><p>入队时，建立一个新结点，将新结点插入到链表的尾部，并让 <code>Q.rear</code> 指向这个新插入的结点（若原队列为空队，则令 <code>Q.front</code> 也指向该结点）。出队时，首先判断队是否为空，若不空，则取出队首元素，将其从链表中删除，并让 <code>Q.front</code> 指向下一个结点（若该结点为最后一个结点，则置 <code>Q.front</code> 和 <code>Q.rear</code> 都为 <code>NULL</code>）。</p><br><p>不难看出，不带头结点的链式队列在操作上往往比较麻烦，因此通常将链式队列设计成一个带头结点的单链表，这样插入和删除操作就统一了，如图所示。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="`+l+'" alt="链栈" width="350px" style="border-radius:10px;"></div><br><p>用单链表表示的链式队列特别适合于数据元素变动比较大的情形，而且不存在队列满且产生溢出的问题。另外，假如程序中要使用多个队列，与多个栈的情形一样，最好使用链式队列，这样就不会出现存储分配不合理和“溢出”的问题。</p><h2 id="链式队列的基本操作" tabindex="-1">链式队列的基本操作 <a class="header-anchor" href="#链式队列的基本操作" aria-label="Permalink to &quot;链式队列的基本操作&quot;">​</a></h2><h3 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h3><h3 id="判队空" tabindex="-1">判队空 <a class="header-anchor" href="#判队空" aria-label="Permalink to &quot;判队空&quot;">​</a></h3><h3 id="入队" tabindex="-1">入队 <a class="header-anchor" href="#入队" aria-label="Permalink to &quot;入队&quot;">​</a></h3><h3 id="出队" tabindex="-1">出队 <a class="header-anchor" href="#出队" aria-label="Permalink to &quot;出队&quot;">​</a></h3>',22)]))}const E=s(r,[["render",p]]);export{b as __pageData,E as default};
